{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C10", "C18", "C83", "C147", "C130", "C154", "C128", "C114"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C10", "C18", "C83", "C147", "C130"],
  "claims": [
    {
      "claim": "The query is pitavastatin free acid; the closest measured context, cerivastatin, shares the 3,5-dihydroxyhept-6-enoic acid side chain and a fluorophenyl substituent and had absolute oral bioavailability 60% (90% CI 51-70%) in fasted healthy young men, with the lower bound well above the 20% threshold.",
      "card_ids": ["C10", "C18"]
    },
    {
      "claim": "L3 card C83 shows that after an oral pitavastatin microdose, the pitavastatin lactone metabolite was measurable in plasma (rifampin GMR ~0.9 for Cmax and AUC), confirming oral absorption and systemic exposure of the pitavastatin scaffold; this is supportive but does not quantify absolute F.",
      "card_ids": ["C83"]
    },
    {
      "claim": "L4 cards C147, C130, C154, C128, and C114 support adequate solubility/dissolution and intestinal permeability for the acidic statin class (cerivastatin sodium freely soluble with rapid dissolution; atorvastatin Caco-2 AP-BL Papp 1.8e-6 cm/s; pH-dependent solubility for acidic statins).",
      "card_ids": ["C147", "C130", "C154", "C128", "C114"]
    },
    {
      "claim": "L5 card C193 shows cerivastatin undergoes intestinal CYP3A metabolism, yet the same molecule has measured F=60% (C10/C18), so intestinal metabolism in this class does not imply F<20%; L5 cards C198/C179 show fluvastatin is an OATP2B1 substrate, supporting possible intestinal uptake for the statin side-chain class, while no pitavastatin-specific efflux/metabolism record is present.",
      "card_ids": ["C193", "C198", "C179"]
    },
    {
      "claim": "L5 cards C171 and C206 identify fluvastatin as an intestinal BCRP substrate and BCRP-mediated efflux, but this is mechanism-only evidence for a different statin core and does not provide threshold-relevant evidence for pitavastatin F<20%.",
      "card_ids": ["C171", "C206"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C193", "C198", "C179", "C171", "C206"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for pitavastatin free acid is present in the supplied cards.",
    "No pitavastatin-specific L5 gut-wall efflux or intestinal-metabolism record is present; the closest L5 records are for cerivastatin, fluvastatin, rosuvastatin, and atorvastatin, which differ in core structure.",
    "Transfer from cerivastatin F=60% does not control for differences in the quinoline/cyclopropyl core versus the cerivastatin pyridine core, transporter profile, or first-pass metabolism.",
    "L5 does not quantify pitavastatin-specific BCRP/P-gp efflux or intestinal CYP metabolism; mechanism alone is not a direct F result.",
    "First-pass hepatic metabolism for pitavastatin is not directly measured in the supplied cards."
  ],
  "decision_summary": "Query is pitavastatin free acid. The closest measured context, cerivastatin, has absolute oral bioavailability 60% (90% CI 51-70%), far above the 20% threshold. L3 confirms oral absorption of the pitavastatin scaffold; L4 supports statin-class solubility and permeability; L5 adds only mechanistic gut-wall efflux/intestinal-metabolism evidence for other statins, with the closest cerivastatin card showing intestinal CYP3A metabolism yet F=60%. No transferable threshold-relevant low-F evidence appears. Prediction remains high with moderate confidence."
}

